#nullable enable // autogenerated

using System;
using System.Collections.Generic;
using MVZ2.UI;
using MVZ2Logic.Inputs;
using MVZ2Logic.Models;
using PVZEngine;
using PVZEngine.Tools.Unity;
using UnityEngine;
using UnityEngine.EventSystems;

namespace MVZ2.Customize
{
    public class TeleporterTeamLayoutUI : MonoBehaviour
    {
        public void SetTileCount(int count)
        {
            tilesList.updateList(count, null, go =>
            {
                var tile = go.GetComponent<TeleporterTeamLayoutTileUI>();
                tile.OnPointerInteraction += OnTilePointerInteractionCallback;
            },
            go =>
            {
                var tile = go.GetComponent<TeleporterTeamLayoutTileUI>();
                tile.OnPointerInteraction -= OnTilePointerInteractionCallback;
            });
        }
        public void ClearTiles()
        {
            foreach (var tile in tilesList.getElements<TeleporterTeamLayoutTileUI>()) 
            {
                tile.ClearLayerModels();
            }
        }
        public void AddTileEntity(int index, NamespaceID entityID, IModelBuilder modelBuilder)
        {
            var tile = tilesList.getElement<TeleporterTeamLayoutTileUI>(index);
            if (tile == null)
                return;
            tile.AddEntityModel(entityID, modelBuilder);
        }
        public void RemoveTileEntity(int index, NamespaceID entityID)
        {
            var tile = tilesList.getElement<TeleporterTeamLayoutTileUI>(index);
            if (tile == null)
                return;
            tile.RemoveEntityModel(entityID);
        }
        private void OnTilePointerInteractionCallback(TeleporterTeamLayoutTileUI tile, PointerEventData eventData, PointerInteraction interaction)
        {
            OnPointerInteraction?.Invoke(tilesList.indexOf(tile), eventData, interaction);
        }
        public event Action<int, PointerEventData, PointerInteraction>? OnPointerInteraction;
        [SerializeField]
        private ElementList tilesList = null!;
    }
}
